function smallestTruck(weights: number[], days: number): number {
  const fits = (cap: number) => {
    let used = 1, load = 0;
    for (const w of weights) {
      if (load + w > cap) { used++; load = 0; }
      load += w;
    }
    return used <= days;
  };
  let cap = Math.max(...weights);
  while (!fits(cap)) cap++;
  return cap;
}

