function smallestTruck(weights: number[], days: number): number {
  const fits = (cap: number) => {
    let used = 1, load = 0;
    for (const w of weights) {
      if (load + w > cap) { used++; load = 0; }
      load += w;
    }
    return used <= days;
  };
  let lo = 0, hi = 0;
  for (const w of weights) { lo = Math.max(lo, w); hi += w; }
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (fits(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

